#include <map>
#include <string>
#include <iostream>

// Assuming IgnoreCaseCmp from Concept 1
struct IgnoreCaseCmp { /* ... definition ... */ };

int main() {
    // Multimap allows equivalent keys defined by the comparator
    std::multimap<std::string, int, IgnoreCaseCmp> mm;

    mm.insert({"Apple", 1});
    mm.insert({"apple", 2}); 

    // Size is 2, both values are retained.
    std::cout << mm.size() << std::endl; // Output: 2

    // Find all equivalent elements (requires equal_range)
    auto range = mm.equal_range("apple");
    for (auto it = range.first; it != range.second; ++it) {
        std::cout << it->first << ": " << it->second << "\n";
    }
}
